<template>
 <div class="people-centre space-y-5">
  <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-bold text-ink">People centre</h2><p class="text-sm text-muted">Policies, holidays, reporting and payroll.</p></div><div class="segmented"><button v-for="item in sections" :key="item.id" :class="section===item.id?'btn-primary':'btn-secondary'" @click="section=item.id">{{ item.label }}</button></div></div>
  <p v-if="error" role="alert" class="alert-error">{{error}}</p><p v-if="notice" role="status" class="alert-ok">{{notice}}</p>
  <template v-if="data">
   <template v-if="section==='guide'">
    <section class="card guide-intro">
     <div class="flex flex-wrap items-center justify-between gap-3"><h3 class="title">Team policy charter</h3><span class="guide-effective">Effective {{dateLabel(data.settings.effective_from)}}</span></div>
     <p v-if="data.reporting_manager" class="guide-manager"><span>Your reporting manager</span><strong>{{data.reporting_manager}}</strong></p>
    </section>
    <div class="guide-grid">
     <section v-for="group in guideSections" :key="group.title" class="card guide-section">
      <h3 class="title">{{group.title}}</h3>
      <ul class="guide-points"><li v-for="point in group.points" :key="point.label"><strong>{{point.label}}:</strong> {{point.text}}</li></ul>
     </section>
    </div>
    <section class="card guide-section"><h3 class="title">Who to contact</h3><div class="guide-contact-grid">
     <div v-for="contact in data.settings.contacts" :key="contact.area" class="guide-contact"><h4>{{contact.area}}</h4><ul class="guide-points"><li><strong>{{contact.name}}</strong><span v-if="contact.title"> · {{contact.title}}</span></li><li>{{contact.details}}</li></ul></div>
    </div></section>
    <section v-if="data.salary_slips?.length" class="card guide-section"><h3 class="title">My payslips</h3><div v-for="slip in data.salary_slips" :key="slip.name" class="guide-payslip"><h4>{{dateLabel(slip.start_date)}} – {{dateLabel(slip.end_date)}}</h4><dl class="guide-pay-values"><div><dt>Gross pay</dt><dd>{{money(slip.gross_pay)}}</dd></div><div><dt>Employee deductions</dt><dd>{{money(slip.total_deduction)}}</dd></div><div><dt>Net pay</dt><dd>{{money(slip.net_pay)}}</dd></div><div><dt>Employer PF</dt><dd>{{money(slip.sf_employer_pf)}}</dd></div></dl></div></section>
   </template>
   <template v-if="section==='holidays'">
    <section class="card space-y-4"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="title">Holiday calendar</h3><p class="text-sm text-muted">{{data.fixed_count}} / 12 fixed holidays configured · {{data.optional_used}} / {{data.optional_limit}} optional holidays reserved or used</p></div><label class="field">Year<input v-model.number="year" type="number" min="2024" max="2100" @change="load" /></label></div><p class="text-sm text-muted">Festival dates require HR confirmation. An incomplete calendar will show only the published dates.</p>
     <div v-for="row in data.holidays" :key="row.name" class="flex flex-wrap items-center justify-between gap-3 border-t border-line pt-3"><div><strong>{{row.holiday_name}}</strong><p class="text-sm text-muted">{{row.holiday_date}} · {{row.kind}}{{row.enabled?'':' · Disabled'}}</p></div><button v-if="row.kind==='Optional' && row.enabled && data.employee" class="btn-secondary" @click="$emit('request-holiday',row.holiday_date)">Request day off</button><button v-if="data.can_manage" class="btn-secondary" @click="editHoliday(row)">Edit</button></div><p v-if="!data.holidays.length" class="text-muted">HR has not published holidays for this year yet.</p>
    </section>
    <form v-if="data.can_manage" class="card space-y-4" @submit.prevent="saveHoliday"><h3 class="title">{{holiday.name?'Edit holiday':'Add holiday'}}</h3><div class="form-grid"><label class="field">Holiday name<input v-model.trim="holiday.holiday_name" list="holiday-names" required maxlength="140" /></label><datalist id="holiday-names"><option v-for="name in [...data.fixed_names,...data.optional_names]" :key="name">{{name}}</option></datalist><label class="field">Date<input v-model="holiday.holiday_date" type="date" :min="data.today" required /></label><label class="field">Type<select aria-label="Holiday type" v-model="holiday.kind"><option>Fixed</option><option>Optional</option></select></label><label class="flex gap-2 items-center"><input v-model="holiday.enabled" type="checkbox" />Published</label></div><label class="field">Reason for calendar change<textarea v-model.trim="holidayReason" minlength="10" required rows="2"></textarea></label><div class="flex justify-end gap-3"><button v-if="holiday.name" type="button" class="btn-secondary" @click="editHoliday({})">Cancel edit</button><button class="btn-primary" :disabled="busy">Save holiday</button></div></form>
   </template>
   <template v-if="section==='payroll' && data.can_payroll">
    <form class="card space-y-4" @submit.prevent="saveLedgers"><h3 class="title">Payroll liability ledgers</h3><p class="text-sm text-muted">These ledgers receive the employee deductions when payroll is posted.</p><div class="form-grid"><label class="field">PF payable ledger<select aria-label="PF payable ledger" v-model="pfLedger" required><option value="">Choose ledger</option><option v-for="account in data.liability_accounts" :key="account.name" :value="account.name">{{account.account_name}}</option></select></label><label class="field">Professional Tax payable ledger<select aria-label="Professional Tax payable ledger" v-model="ptLedger" required><option value="">Choose ledger</option><option v-for="account in data.liability_accounts" :key="account.name" :value="account.name">{{account.account_name}}</option></select></label></div><label class="field">Reason for payroll ledger change<textarea v-model.trim="ledgerReason" minlength="10" required rows="2"></textarea></label><button class="btn-secondary" :disabled="busy">Save payroll ledgers</button></form>
    <section class="card space-y-4"><h3 class="title">Employee payroll setup</h3><p class="text-sm text-muted">Enrol PF and Professional Tax per employee. Monthly salary values are used for the preview; the actual payslip uses its salary structure and earnings.</p><label class="field">Employee<select aria-label="Payroll employee" v-model="payrollEmployee" @change="loadProfile"><option value="">Choose employee</option><option v-for="person in data.people" :key="person.name" :value="person.name">{{person.employee_name}}</option></select></label></section>
    <form v-if="profile" class="card space-y-4" @submit.prevent="saveProfile"><div class="form-grid"><label class="field">Effective from<input type="date" v-model="profile.effective_from" required /></label><label class="field">Basic salary component<input v-model="profile.basic_component" placeholder="Basic" /></label><label class="field">Monthly basic (INR)<input v-model.number="profile.monthly_basic" type="number" min="0" step="0.01" required /></label><label class="field">Monthly gross (INR)<input v-model.number="profile.monthly_gross" type="number" min="0" step="0.01" required /></label><label class="field">Payroll state<select v-model="profile.payroll_state"><option>Maharashtra</option><option>Other</option></select></label></div><div class="flex gap-5 flex-wrap"><label><input v-model="profile.pf_enrolled" :true-value="1" :false-value="0" type="checkbox" /> PF enrolled</label><label><input v-model="profile.pt_applicable" :true-value="1" :false-value="0" type="checkbox" /> Professional Tax applies</label><label><input v-model="profile.pt_exempt" :true-value="1" :false-value="0" type="checkbox" /> PT exempt</label></div><label v-if="profile.pt_exempt" class="field">PT exemption reason<textarea v-model="profile.pt_exemption_reason" minlength="10" required rows="2"></textarea></label><p class="text-sm text-muted">The company policy uses a ₹25,000 PF wage cap. Higher-wage PF requires the applicable employee/employer arrangement. Employer PF is recorded separately from employee deductions.</p><label class="field">Reason for payroll change<textarea v-model.trim="profileReason" minlength="10" required rows="2"></textarea></label><button class="btn-primary" :disabled="busy">Save payroll profile</button></form>
    <section v-if="profile" class="card space-y-4"><h3 class="title">Salary calculation preview</h3><div class="form-grid"><label class="field">Payroll month<input type="month" v-model="payrollMonth" /></label><label class="field">Unpaid equivalent days<input v-model.number="unpaidDays" type="number" min="0" max="31" step="0.5" /></label></div><button class="btn-secondary" :disabled="busy" @click="previewSalary">Preview calculation</button><div v-if="preview" class="rounded-xl bg-soft p-4 space-y-2 text-sm"><p>Calendar days: <strong>{{preview.calendar_days}}</strong> · Unpaid days: <strong>{{preview.unpaid_days}}</strong></p><p>Salary reduction: {{money(preview.salary_reduction)}}</p><p>Gross after absence: {{money(preview.gross_after_absence)}}</p><p>Employee PF: {{money(preview.employee_pf)}} · Professional Tax: {{money(preview.professional_tax)}}</p><p>Employer PF: {{money(preview.employer_pf)}}</p><p class="font-semibold">Net before other deductions: {{money(preview.net_before_other_deductions)}}</p><p class="text-xs text-muted">Preview only. Submitted payslips remain the accounting record.</p></div></section>
    <section v-if="profileHistory.length" class="card"><h3 class="title">Payroll profile history</h3><div v-for="row in profileHistory" :key="row.name" class="border-t border-line py-3 text-sm"><strong>Effective {{row.effective_from}}</strong><p>{{row.reason}}</p><p class="text-muted">{{row.author}} · {{row.published_on}}</p></div></section>
   </template>
   <section v-if="section==='handbook' && data.can_manage" class="card space-y-4"><h3 class="title">Employee role and reporting</h3><p class="text-sm text-muted">Link actual employee records to the organisation. Changing employment type also controls salaried-only attendance and leave automation.</p><label class="field">Employee<select aria-label="Reporting employee" v-model="roleEmployee" @change="loadReporting"><option value="">Choose employee</option><option v-for="person in data.people" :key="person.name" :value="person.name">{{person.employee_name}}</option></select></label><template v-if="reporting"><label class="field">Designation<input v-model="reporting.designation" list="organisation-designations" required /></label><datalist id="organisation-designations"><option v-for="position in data.settings.positions" :key="position.id">{{position.title}}</option></datalist><label class="field">Reporting manager<select aria-label="Reporting manager" v-model="reporting.reports_to"><option value="">No reporting manager</option><option v-for="person in data.people.filter(x=>x.name!==roleEmployee)" :key="person.name" :value="person.name">{{person.employee_name}}</option></select></label><label class="field">Employment type<select aria-label="Employment type" v-model="reporting.employment_type"><option value="" disabled>Choose employment type</option><option v-for="type in data.employment_types" :key="type">{{type}}</option></select></label><label class="field">Reason for employee change<textarea v-model.trim="reportingReason" minlength="10" rows="2"></textarea></label><button class="btn-primary" :disabled="busy || reportingReason.length<10" @click="saveReporting">Save employee reporting</button></template></section>
   <form v-if="section==='handbook' && data.can_manage" class="card space-y-5" @submit.prevent="publishHandbook"><h3 class="title">Edit organisation and guidance</h3><label class="field">Working-day availability<textarea v-model="handbook.availability" required rows="3"></textarea></label><label class="field">Notice and exit terms<textarea v-model="handbook.exit_terms" required rows="2"></textarea></label><div v-for="position in handbook.positions" :key="position.id" class="border-t border-line pt-4 form-grid"><label class="field">Name<input v-model="position.name" required /></label><label class="field">Role<input v-model="position.title" required /></label><label class="field">Reports to position<select v-model="position.manager_id"><option value="">No direct reporting line</option><option v-for="parent in handbook.positions.filter(x=>x.id!==position.id)" :key="parent.id" :value="parent.id">{{parent.name}} · {{parent.title}}</option></select></label><label class="field">Functional line<input v-model="position.functional_line" /></label></div><div v-for="contact in handbook.contacts" :key="contact.area" class="form-grid border-t border-line pt-4"><label class="field">Contact area<input v-model="contact.area" /></label><label class="field">Contact name<input v-model="contact.name" /></label><label class="field">Contact role<input v-model="contact.title" /></label><label class="field">Help with<input v-model="contact.details" /></label></div><label class="field">Reason for handbook change<textarea v-model.trim="handbookReason" minlength="10" required rows="2"></textarea></label><p class="text-sm text-muted">The published organisation guide describes roles. Use Employee role and reporting above to update actual employee records.</p><button class="btn-primary" :disabled="busy">Publish handbook revision</button></form>
  </template>
 </div>
</template>
<script setup>
import {computed,onMounted,ref,reactive} from 'vue';
import {call} from '../lib/frappe';
defineEmits(['request-holiday']);
const API='volunteering.volunteering.hr_resources.';
const data=ref(null),section=ref('guide'),year=ref(new Date().getFullYear()),busy=ref(false),error=ref(''),notice=ref('');
const pfLedger=ref(''),ptLedger=ref(''),ledgerReason=ref('');
const roleEmployee=ref(''),reporting=ref(null),reportingReason=ref('');
const holiday=reactive({}),holidayReason=ref(''),payrollEmployee=ref(''),profile=ref(null),profileHistory=ref([]),profileReason=ref(''),payrollMonth=ref(new Date().toISOString().slice(0,7)),unpaidDays=ref(0),preview=ref(null),handbook=reactive({}),handbookReason=ref('');
const sections=computed(()=>[{id:'guide',label:'Guide'},{id:'holidays',label:'Holidays'},...(data.value?.can_payroll?[{id:'payroll',label:'Payroll'}]:[]),...(data.value?.can_manage?[{id:'handbook',label:'Edit guide'}]:[])]);
const money=value=>Number(value||0).toLocaleString('en-IN',{style:'currency',currency:'INR'});
const dateLabel=value=>new Date(`${value}T12:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const monthLabel=value=>new Date(2000,Number(value)-1,1).toLocaleDateString('en-IN',{month:'long'});
const guideSections=computed(()=>{
 const p=data.value?.guide_policy||{},settings=data.value?.settings||{},profile=data.value?.payroll_profile;
 const half=p.half_day_hours??3,full=p.full_day_hours??6;
 const groups=[
  {title:'Work logs and attendance',points:[
   {label:'Log your work',text:`Within ${p.work_log_days??4} calendar days of the work date.`},
   {label:'Full day',text:`${full} hours or more.`},
   {label:'Half day',text:`${half} to under ${full} hours.`},
   {label:`Under ${half} hours`,text:'Unpaid unless approved leave or an HR correction covers the absence.'}]},
  {title:'Paid leave and approvals',points:[
   {label:'Leave earned',text:`${p.monthly_leave??2.5} days each month (${Number(p.monthly_leave??2.5)*12} days a year).`},
   {label:'Carry-forward',text:`Up to ${p.carry_forward_days??15} days into the next leave year.`},
   {label:'Leave year',text:`Begins in ${monthLabel(p.leave_year_start_month??1)}.`},
   {label:'Short leave',text:`Up to ${p.short_leave_days??3} days: give the same number of days’ notice.`},
   {label:'Longer leave',text:`Give at least ${p.extended_notice_days??14} days’ notice.`},
   {label:'Approval',text:'Your reporting manager approves leave and weekly-off swaps.'}]},
  {title:'Compensatory leave',points:[
   {label:'Credit',text:`${p.comp_hours??6}+ hours worked on an eligible day earns one day. Shorter work needs HR review.`},
   {label:'Use within',text:`${p.comp_valid_months??2} months of the eligible work date.`}]},
  {title:'Medical leave',points:[
   {label:'Inform your manager',text:(p.medical_notice_days??0)===0?'The same day. Advance notice is waived for sudden illness.':`Within ${p.medical_notice_days} days. Advance notice is waived for sudden illness.`},
   {label:'Medical certificate',text:`Required before approval for more than ${p.medical_certificate_days??2} consecutive days.`}]},
  {title:'Parental leave',points:[
   {label:'Maternity',text:`Up to ${p.maternity_weeks??26} paid weeks for eligible employees. HR verifies the applicable entitlement.`},
   {label:'Paternity',text:`${p.paternity_days??5} paid working days within ${p.paternity_window_months??3} months of childbirth.`},
   {label:'Approval',text:'HR verifies eligibility first; your reporting manager decides the request.'},
   {label:'Separate allowances',text:'Parental leave and optional holidays do not use your annual paid-leave balance.'}]},
  {title:'Salary and deductions',points:[
   {label:'Salary calculation',text:p.calendar_day_payroll===0?'Uses the configured payroll calendar.':'Uses the actual calendar days in the month.'},
   {label:'Amount paid',text:'Based on approved attendance, leave and unpaid days.'},
   {label:'Employee PF',text:`${p.pf_employee_rate??12}% of eligible Basic for enrolled employees.`},
   {label:'Employer PF',text:`Sevamrita contributes ${p.pf_employer_rate??12}% separately; this is not deducted from your take-home pay.`},
   {label:'Company PF wage cap',text:Number(p.pf_wage_ceiling??25000)>0?money(p.pf_wage_ceiling??25000):'No company wage cap configured.'},
   {label:'Maharashtra Professional Tax',text:`The upper band is ${money(p.pt_regular_rate??200)} monthly, or ${money(p.pt_february_rate??300)} in February. Salary thresholds and exemptions apply.`},
   {label:'Enrolment',text:'HR confirms PF enrolment and Professional Tax applicability or exemptions.'}]},
  {title:'Working arrangements',points:[
   {label:'Availability',text:settings.availability||''},
   {label:'Notice and exit',text:settings.exit_terms||''}].filter(point=>point.text)}
 ];
 if(p.director_approval_days>0)groups[1].points.push({label:'Extended approval',text:`Leave above ${p.director_approval_days} days requires Director approval.`});
 if(profile)groups.push({title:'Your payroll profile',points:[
  {label:'Effective from',text:dateLabel(profile.effective_from)},
  {label:'PF',text:profile.pf_enrolled?'Enrolled.':'Not enrolled.'},
  {label:'Professional Tax',text:profile.pt_applicable&&!profile.pt_exempt?'Applies.':'Not applicable or exempt.'}]});
 return groups;
});
async function operation(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){await operation(async()=>{data.value=await call(API+'get_people_centre',{year:year.value});Object.assign(handbook,JSON.parse(JSON.stringify(data.value.settings)));pfLedger.value=data.value.payroll_accounts?.['SF Employee PF']||'';ptLedger.value=data.value.payroll_accounts?.['SF Professional Tax']||'';});}
function editHoliday(row){Object.assign(holiday,{name:'',modified:'',holiday_name:'',holiday_date:'',kind:'Fixed',enabled:true},row,{enabled:row.enabled===undefined?true:!!row.enabled});holidayReason.value='';}
async function saveHoliday(){await operation(async()=>{data.value=await call(API+'save_holiday',{details:{...holiday},reason:holidayReason.value,expected_modified:holiday.modified});year.value=data.value.year;editHoliday({});notice.value='Holiday calendar updated.';});}
async function saveLedgers(){await operation(async()=>{await call(API+'configure_payroll_ledgers',{pf_account:pfLedger.value,pt_account:ptLedger.value,reason:ledgerReason.value});ledgerReason.value='';notice.value='Payroll liability ledgers configured.';});}
async function loadProfile(){profile.value=null;preview.value=null;if(!payrollEmployee.value)return;await operation(async()=>{const result=await call(API+'get_payroll_profile',{employee:payrollEmployee.value});profile.value=result.profile;profileHistory.value=result.history;profileReason.value='';});}
async function saveProfile(){await operation(async()=>{const result=await call(API+'save_payroll_profile',{details:profile.value,reason:profileReason.value,expected_modified:profile.value.modified});profile.value=result.profile;profileHistory.value=result.history;profileReason.value='';notice.value='Effective payroll profile saved.';});}
async function previewSalary(){await operation(async()=>{preview.value=await call(API+'preview_payroll',{employee:payrollEmployee.value,month:payrollMonth.value,unpaid_days:unpaidDays.value});});}
async function loadReporting(){reporting.value=null;if(!roleEmployee.value)return;await operation(async()=>{reporting.value=await call(API+'get_employee_reporting',{employee:roleEmployee.value});reporting.value.reports_to=reporting.value.reports_to||'';reportingReason.value='';});}
async function saveReporting(){await operation(async()=>{reporting.value=await call(API+'save_employee_reporting',{employee:roleEmployee.value,reports_to:reporting.value.reports_to||'',designation:reporting.value.designation,employment_type:reporting.value.employment_type||undefined,expected_modified:reporting.value.modified,reason:reportingReason.value});reportingReason.value='';notice.value='Employee role and reporting updated.';});}
async function publishHandbook(){await operation(async()=>{const result=await call(API+'save_charter',{settings:{...handbook},expected_revision:data.value.revision,reason:handbookReason.value});data.value={...data.value,...result};handbookReason.value='';notice.value='Handbook revision published.';});}
onMounted(()=>{editHoliday({});load();});
</script>
<style scoped>
.card{background:var(--surface);border:1px solid var(--line);border-radius:1rem;padding:1.4rem;min-width:0;box-shadow:var(--shadow-soft)}.title{font-size:1.1rem;font-weight:700;color:var(--ink)}.form-grid,.policy-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.2rem;background:transparent;padding:0;border:0}.policy-grid p{margin-top:.4rem;font-size:.875rem;line-height:1.6;color:var(--muted)}.field{display:flex;flex-direction:column;gap:.45rem;font-size:.875rem;font-weight:600;min-width:0;background:transparent;padding:0;border:0}.field input,.field textarea,.field select{display:block;width:100%;min-width:0;min-height:2.9rem;border:1px solid var(--line);border-radius:.7rem;padding:.7rem .8rem;background:var(--surface);font-size:1rem;font-weight:400;color:var(--ink)}.field input:focus-visible,.field textarea:focus-visible,.field select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.alert-error,.alert-ok{border-radius:.8rem;padding:.9rem 1rem;font-size:.875rem}.alert-error{background:var(--bad-soft);color:var(--bad)}.alert-ok{background:var(--ok-soft)}input[type=checkbox]{accent-color:var(--accent);width:1rem;height:1rem}p{overflow-wrap:anywhere}@media(max-width:640px){.form-grid,.policy-grid{grid-template-columns:minmax(0,1fr)}.card{padding:1.1rem}}

.guide-intro{display:flex;flex-direction:column;gap:1rem}.guide-effective{font-size:.8rem;font-weight:600;color:var(--accent);white-space:nowrap}.guide-manager{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.4rem;background:var(--soft);padding:.8rem 1rem;border-radius:.7rem;font-size:.875rem}.guide-manager span{color:var(--muted)}.guide-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;align-items:start}.guide-section .title{margin:0 0 .85rem}.guide-points{list-style:disc;margin:0;padding:0 0 0 1.15rem;display:grid;gap:.65rem;font-size:.9rem;line-height:1.6;color:var(--ink)}.guide-points li{padding-left:.15rem;overflow-wrap:anywhere}.guide-points li::marker{color:var(--accent)}.guide-points strong{font-weight:600}.guide-contact-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1.25rem}.guide-contact h4,.guide-payslip h4{margin:0 0 .65rem;font-size:.95rem;font-weight:600}.guide-payslip{padding:1rem 0;border-top:1px solid var(--line)}.guide-pay-values{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;font-size:.875rem}.guide-pay-values dt{color:var(--muted);margin-bottom:.15rem}.guide-pay-values dd{font-weight:600}@media(max-width:700px){.guide-grid{grid-template-columns:minmax(0,1fr)}}
</style>
